import { LoadingButton } from '@/components/ui/loading-button';
import { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import { UserPlus, Eye, EyeOff, Copy, CheckCircle } from 'lucide-react';
import { useUserManagement, Partner } from '@/hooks/useUserManagement';

interface CreateUserModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  currentUserRole: 'admin' | 'super_admin';
}

const CreateUserModal = ({ open, onOpenChange, currentUserRole }: CreateUserModalProps) => {
  const { createUser, fetchPartners, partners, loading } = useUserManagement();
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<'partner' | 'admin' | 'super_admin'>('partner');
  const [partnerId, setPartnerId] = useState<string>('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [createdUser, setCreatedUser] = useState<{ email: string; password: string } | null>(null);

  useEffect(() => {
    if (open) {
      fetchPartners();
    }
  }, [open, fetchPartners]);

  const generatePassword = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%';
    let pwd = '';
    for (let i = 0; i < 14; i++) {
      pwd += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    setPassword(pwd);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!email || !password) {
      return;
    }

    if (role === 'partner' && !partnerId) {
      return;
    }

    const result = await createUser(
      email,
      role,
      role === 'partner' ? partnerId : null,
      password
    );

    if (result.success) {
      setCreatedUser({ email, password });
    }
  };

  const resetForm = () => {
    setEmail('');
    setRole('partner');
    setPartnerId('');
    setPassword('');
    setShowPassword(false);
    setCreatedUser(null);
  };

  const handleClose = () => {
    resetForm();
    onOpenChange(false);
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  if (createdUser) {
    return (
      <Dialog open={open} onOpenChange={handleClose}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <CheckCircle className="h-5 w-5 text-success" />
              User Created Successfully!
            </DialogTitle>
            <DialogDescription>
              Save these credentials - they won't be shown again
            </DialogDescription>
          </DialogHeader>

          <Alert>
            <UserPlus className="h-4 w-4" />
            <AlertDescription>
              <div className="space-y-3">
                <div>
                  <Label className="text-xs">Email:</Label>
                  <div className="flex items-center gap-2 mt-1">
                    <code className="text-sm bg-muted px-2 py-1 rounded flex-1">{createdUser.email}</code>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => copyToClipboard(createdUser.email)}
                      className="h-7 px-2"
                    >
                      <Copy className="h-3 w-3" />
                    </Button>
                  </div>
                </div>
                <div>
                  <Label className="text-xs">Password:</Label>
                  <div className="flex items-center gap-2 mt-1">
                    <code className="text-sm bg-muted px-2 py-1 rounded flex-1">{createdUser.password}</code>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => copyToClipboard(createdUser.password)}
                      className="h-7 px-2"
                    >
                      <Copy className="h-3 w-3" />
                    </Button>
                  </div>
                </div>
              </div>
            </AlertDescription>
          </Alert>

          <DialogFooter className="sm:justify-between">
            <Button variant="outline" onClick={resetForm}>
              Create Another
            </Button>
            <Button onClick={handleClose}>Done</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    );
  }

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <UserPlus className="h-5 w-5" />
            Create New User
          </DialogTitle>
          <DialogDescription>
            Add a new user to the system with login credentials
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-3">
            <div>
              <Label htmlFor="email">Email *</Label>
              <Input
                id="email"
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="user@example.com"
                required
              />
            </div>

            <div>
              <Label htmlFor="role">Role *</Label>
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              <Select value={role} onValueChange={(v) => setRole(v as any)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="partner">Partner</SelectItem>
                  <SelectItem value="admin">Admin</SelectItem>
                  {currentUserRole === 'super_admin' && (
                    <SelectItem value="super_admin">Super Admin</SelectItem>
                  )}
                </SelectContent>
              </Select>
              {role === 'admin' && (
                <p className="text-xs text-muted-foreground mt-1">
                  Admins can view and manage all leads and partners
                </p>
              )}
            </div>

            {role === 'partner' && (
              <div>
                <Label htmlFor="partner">Assign to Partner *</Label>
                <Select value={partnerId} onValueChange={setPartnerId}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select partner..." />
                  </SelectTrigger>
                  <SelectContent>
                    {partners.map((p) => (
                      <SelectItem key={p.id} value={p.id}>
                        {p.name} ({p.partner_code})
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            <div>
              <Label htmlFor="password">Password *</Label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <Input
                    id="password"
                    type={showPassword ? 'text' : 'password'}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="Secure password"
                    required
                  />
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    className="absolute right-0 top-0 h-full px-3"
                    onClick={() => setShowPassword(!showPassword)}
                  >
                    {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                  </Button>
                </div>
                <Button type="button" variant="outline" onClick={generatePassword}>
                  Generate
                </Button>
              </div>
            </div>
          </div>

          {role === 'admin' && (
            <Alert>
              <UserPlus className="h-4 w-4" />
              <AlertDescription className="text-xs">
                Admins can view and manage all partners and students system-wide
              </AlertDescription>
            </Alert>
          )}

          <DialogFooter>
            <Button type="button" variant="outline" onClick={handleClose} disabled={loading}>
              Cancel
            </Button>
            <LoadingButton type="submit" loading={loading} loadingText="Creating...">
              Create User
            </LoadingButton>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default CreateUserModal;

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { formatCurrency } from '@/utils/formatters';
import { getExpenseIcon } from '@/utils/lenderIcons';
import { Loader2, Mail, Phone, Globe, TrendingUp, Clock, DollarSign, CheckCircle2, FileText } from 'lucide-react';

interface Lender {
  id: string;
  name: string;
  code: string;
  description: string | null;
  is_active: boolean;
  interest_rate_min: number | null;
  interest_rate_max: number | null;
  loan_amount_min: number | null;
  loan_amount_max: number | null;
  processing_fee: number | null;
  foreclosure_charges: number | null;
  processing_time_days: number | null;
  disbursement_time_days: number | null;
  approval_rate: number | null;
  moratorium_period: string | null;
  contact_email: string | null;
  contact_phone: string | null;
  website: string | null;
  logo_url: string | null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  key_features?: any[] | null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  eligible_expenses?: any[] | null;
  required_documents?: string[] | null;
}

interface LenderDetailsSheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  lender: Lender;
}

export function LenderDetailsSheet({
  open,
  onOpenChange,
  lender,
}: LenderDetailsSheetProps) {
  const [stats, setStats] = useState({
    totalLeads: 0,
    activeLeads: 0,
    approvedLeads: 0,
    totalLoanAmount: 0,
    loading: true,
  });

  useEffect(() => {
    if (open && lender) {
      fetchLenderStats();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, lender]);
 

  const fetchLenderStats = async () => {
    try {
      const { data, error } = await supabase
        .from('leads_new')
        .select('id, status, loan_amount')
        .eq('lender_id', lender.id);

      if (error) throw error;

      const totalLeads = data?.length || 0;
      const activeLeads = data?.filter((l) => l.status === 'in_progress').length || 0;
      const approvedLeads = data?.filter((l) => l.status === 'approved').length || 0;
      const totalLoanAmount = data?.reduce((sum, l) => sum + (l.loan_amount || 0), 0) || 0;

      setStats({
        totalLeads,
        activeLeads,
        approvedLeads,
        totalLoanAmount,
        loading: false,
      });
    } catch (error) {
      console.error('Error fetching lender stats:', error);
      setStats((prev) => ({ ...prev, loading: false }));
    }
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="overflow-y-auto w-full sm:max-w-xl">
        <SheetHeader>
          <SheetTitle className="flex items-center gap-2">
            {lender.name}
            <Badge variant={lender.is_active ? 'default' : 'secondary'}>
              {lender.is_active ? 'Active' : 'Inactive'}
            </Badge>
          </SheetTitle>
          <SheetDescription>
            {lender.code} • Detailed lender information and statistics
          </SheetDescription>
        </SheetHeader>

        <div className="mt-6 space-y-6">
          {/* Statistics */}
          <div>
            <h3 className="text-sm font-semibold mb-3">Performance Statistics</h3>
            {stats.loading ? (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-4">
                <div className="p-4 border rounded-lg">
                  <div className="text-2xl font-bold">{stats.totalLeads}</div>
                  <div className="text-sm text-muted-foreground">Total Leads</div>
                </div>
                <div className="p-4 border rounded-lg">
                  <div className="text-2xl font-bold">{stats.activeLeads}</div>
                  <div className="text-sm text-muted-foreground">In Progress</div>
                </div>
                <div className="p-4 border rounded-lg">
                  <div className="text-2xl font-bold">{stats.approvedLeads}</div>
                  <div className="text-sm text-muted-foreground">Approved</div>
                </div>
                <div className="p-4 border rounded-lg">
                  <div className="text-2xl font-bold">{formatCurrency(stats.totalLoanAmount)}</div>
                  <div className="text-sm text-muted-foreground">Total Value</div>
                </div>
              </div>
            )}
          </div>

          <Separator />

          {/* Description */}
          {lender.description && (
            <>
              <div>
                <h3 className="text-sm font-semibold mb-2">About</h3>
                <p className="text-sm text-muted-foreground">{lender.description}</p>
              </div>
              <Separator />
            </>
          )}

          {/* Financial Details */}
          <div>
            <h3 className="text-sm font-semibold mb-3">Financial Details</h3>
            <div className="space-y-3">
              {lender.interest_rate_min && lender.interest_rate_max && (
                <div className="flex items-center gap-2">
                  <TrendingUp className="h-4 w-4 text-muted-foreground" />
                  <span className="text-sm">Interest Rate:</span>
                  <span className="text-sm font-medium ml-auto">
                    {lender.interest_rate_min}% - {lender.interest_rate_max}%
                  </span>
                </div>
              )}
              {lender.loan_amount_min && lender.loan_amount_max && (
                <div className="flex items-center gap-2">
                  <DollarSign className="h-4 w-4 text-muted-foreground" />
                  <span className="text-sm">Loan Range:</span>
                  <span className="text-sm font-medium ml-auto">
                    {formatCurrency(lender.loan_amount_min)} - {formatCurrency(lender.loan_amount_max)}
                  </span>
                </div>
              )}
              {lender.processing_fee && (
                <div className="flex items-center gap-2">
                  <span className="text-sm">Processing Fee:</span>
                  <span className="text-sm font-medium ml-auto">{lender.processing_fee}%</span>
                </div>
              )}
              {lender.foreclosure_charges && (
                <div className="flex items-center gap-2">
                  <span className="text-sm">Foreclosure Charges:</span>
                  <span className="text-sm font-medium ml-auto">{lender.foreclosure_charges}%</span>
                </div>
              )}
            </div>
          </div>

          <Separator />

          {/* Processing Details */}
          <div>
            <h3 className="text-sm font-semibold mb-3">Processing Information</h3>
            <div className="space-y-3">
              {lender.processing_time_days && (
                <div className="flex items-center gap-2">
                  <Clock className="h-4 w-4 text-muted-foreground" />
                  <span className="text-sm">Processing Time:</span>
                  <span className="text-sm font-medium ml-auto">{lender.processing_time_days} days</span>
                </div>
              )}
              {lender.disbursement_time_days && (
                <div className="flex items-center gap-2">
                  <Clock className="h-4 w-4 text-muted-foreground" />
                  <span className="text-sm">Disbursement Time:</span>
                  <span className="text-sm font-medium ml-auto">{lender.disbursement_time_days} days</span>
                </div>
              )}
              {lender.approval_rate && (
                <div className="flex items-center gap-2">
                  <TrendingUp className="h-4 w-4 text-muted-foreground" />
                  <span className="text-sm">Approval Rate:</span>
                  <span className="text-sm font-medium ml-auto">{lender.approval_rate}%</span>
                </div>
              )}
              {lender.moratorium_period && (
                <div className="flex items-center gap-2">
                  <span className="text-sm">Moratorium Period:</span>
                  <span className="text-sm font-medium ml-auto">{lender.moratorium_period}</span>
                </div>
              )}
            </div>
          </div>

          <Separator />

          {/* Key Features */}
          {lender.key_features && lender.key_features.length > 0 && (
            <>
              <div>
                <h3 className="text-sm font-semibold mb-3">Key Features</h3>
                <div className="flex flex-wrap gap-2">
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                  {lender.key_features.map((feature: any, index: number) => (
                     
                    <Badge key={index} variant="outline" className="text-xs font-normal bg-muted/50">
                      <CheckCircle2 className="h-3 w-3 mr-1 text-success" />
                      {typeof feature === 'string' ? feature : feature.name || feature.label}
                    </Badge>
                  ))}
                </div>
              </div>
              <Separator />
            </>
          )}

          {/* Eligible Expenses */}
          {lender.eligible_expenses && lender.eligible_expenses.length > 0 && (
            <>
              <div>
                <h3 className="text-sm font-semibold mb-3">Eligible Expenses</h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                  {lender.eligible_expenses.map((expense: any, index: number) => {
                     
                    const IconComponent = getExpenseIcon(expense.icon);
                    return (
                      <div key={index} className="flex items-start gap-2">
                        <div className="flex-shrink-0 flex items-center justify-center w-8 h-8 rounded-lg bg-primary/10">
                          <IconComponent className="h-4 w-4 text-primary" />
                        </div>
                        <div className="min-w-0">
                          <p className="text-sm font-medium">{expense.category}</p>
                          <p className="text-xs text-muted-foreground">{expense.description}</p>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
              <Separator />
            </>
          )}

          {/* Required Documents */}
          {lender.required_documents && lender.required_documents.length > 0 && (
            <>
              <div>
                <h3 className="text-sm font-semibold mb-3 flex items-center gap-2">
                  <FileText className="h-4 w-4" />
                  Required Documents
                </h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                  {lender.required_documents.map((doc: string, index: number) => (
                    <div key={index} className="flex items-center gap-2 text-sm">
                      <CheckCircle2 className="h-3.5 w-3.5 text-primary flex-shrink-0" />
                      <span className="text-muted-foreground">{doc}</span>
                    </div>
                  ))}
                </div>
              </div>
              <Separator />
            </>
          )}

          {/* Contact Information */}
          <div>
            <h3 className="text-sm font-semibold mb-3">Contact Information</h3>
            <div className="space-y-3">
              {lender.contact_email && (
                <div className="flex items-center gap-2">
                  <Mail className="h-4 w-4 text-muted-foreground" />
                  <a
                    href={`mailto:${lender.contact_email}`}
                    className="text-sm text-primary hover:underline"
                  >
                    {lender.contact_email}
                  </a>
                </div>
              )}
              {lender.contact_phone && (
                <div className="flex items-center gap-2">
                  <Phone className="h-4 w-4 text-muted-foreground" />
                  <a
                    href={`tel:${lender.contact_phone}`}
                    className="text-sm text-primary hover:underline"
                  >
                    {lender.contact_phone}
                  </a>
                </div>
              )}
              {lender.website && (
                <div className="flex items-center gap-2">
                  <Globe className="h-4 w-4 text-muted-foreground" />
                  <a
                    href={lender.website}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-sm text-primary hover:underline"
                  >
                    {lender.website}
                  </a>
                </div>
              )}
            </div>
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
}

import { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { FileQuestion, PenLine, Check } from 'lucide-react';
import { ClarificationTemplate, Clarification } from '@/hooks/useClarifications';
import { cn } from '@/lib/utils';
import { formatDisplayText } from '@/utils/formatters';
import { DatePickerWithYearSelect } from '@/components/ui/date-picker-with-year-select';

interface RaiseClarificationModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  leadId: string;
  templates: ClarificationTemplate[];
  onSubmit: (data: {
    lead_id: string;
    question_type: Clarification['question_type'];
    question_text: string;
    question_context?: string;
    response_type?: Clarification['response_type'];
    is_blocking?: boolean;
    priority?: Clarification['priority'];
    due_date?: string;
    created_by?: string;
    created_by_role?: 'admin' | 'partner' | 'system';
  }) => Promise<Clarification | void>;
  createdBy?: string;
  createdByRole?: 'admin' | 'partner';
}

export function RaiseClarificationModal({
  open,
  onOpenChange,
  leadId,
  templates,
  onSubmit,
  createdBy,
  createdByRole = 'admin',
}: RaiseClarificationModalProps) {
  const [selectedTemplate, setSelectedTemplate] = useState<ClarificationTemplate | null>(null);
  const [customQuestion, setCustomQuestion] = useState('');
  const [customContext, setCustomContext] = useState('');
  const [questionType, setQuestionType] = useState<Clarification['question_type']>('information');
  const [responseType, setResponseType] = useState<Clarification['response_type']>('text');
  const [isBlocking, setIsBlocking] = useState(false);
  const [priority, setPriority] = useState<Clarification['priority']>('normal');
  const [dueDate, setDueDate] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeTab, setActiveTab] = useState('templates');

  const handleSelectTemplate = (template: ClarificationTemplate) => {
    setSelectedTemplate(template);
    setCustomQuestion(template.question_text);
    setCustomContext(template.question_context || '');
    setQuestionType(template.category === 'document' ? 'document' : 'information');
    setResponseType(template.response_type);
  };

  const handleSubmit = async () => {
    const questionText = selectedTemplate ? selectedTemplate.question_text : customQuestion;
    if (!questionText.trim()) return;

    setIsSubmitting(true);
    try {
      await onSubmit({
        lead_id: leadId,
        question_type: questionType,
        question_text: questionText,
        question_context: customContext || undefined,
        response_type: responseType,
        is_blocking: isBlocking,
        priority,
        due_date: dueDate || undefined,
        created_by: createdBy,
        created_by_role: createdByRole,
      });
      resetForm();
      onOpenChange(false);
    } catch (error) {
      // Error handled by hook
    } finally {
      setIsSubmitting(false);
    }
  };

  const resetForm = () => {
    setSelectedTemplate(null);
    setCustomQuestion('');
    setCustomContext('');
    setQuestionType('information');
    setResponseType('text');
    setIsBlocking(false);
    setPriority('normal');
    setDueDate('');
  };

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'document':
        return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'personal':
        return 'bg-purple-100 text-purple-700 border-purple-200';
      case 'academic':
        return 'bg-green-100 text-green-700 border-green-200';
      case 'co_applicant':
        return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'lender':
        return 'bg-red-100 text-red-700 border-red-200';
      default:
        return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[650px] max-h-[90vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FileQuestion className="h-5 w-5" />
            Raise Clarification
          </DialogTitle>
          <DialogDescription>
            Ask the student a question about their application. They will be notified.
          </DialogDescription>
        </DialogHeader>

        <Tabs value={activeTab} onValueChange={setActiveTab} className="flex-1">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="templates" className="flex items-center gap-2">
              <FileQuestion className="h-4 w-4" />
              Templates
            </TabsTrigger>
            <TabsTrigger value="custom" className="flex items-center gap-2">
              <PenLine className="h-4 w-4" />
              Custom
            </TabsTrigger>
          </TabsList>

          <TabsContent value="templates" className="mt-4 flex-1">
            <ScrollArea className="h-[250px] pr-4">
              <div className="space-y-2">
                {templates.map((template) => (
                  <div
                    key={template.id}
                    onClick={() => handleSelectTemplate(template)}
                    className={cn(
                      'p-3 rounded-lg border cursor-pointer transition-all',
                      selectedTemplate?.id === template.id
                        ? 'border-primary bg-primary/5 ring-1 ring-primary'
                        : 'hover:border-muted-foreground/50 hover:bg-muted/50'
                    )}
                  >
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <Badge
                            variant="outline"
                            className={cn('text-xs capitalize', getCategoryColor(template.category))}
                          >
                            {formatDisplayText(template.category)}
                          </Badge>
                          {template.requires_document && (
                            <Badge variant="secondary" className="text-xs">
                              Requires Doc
                            </Badge>
                          )}
                        </div>
                        <p className="text-sm font-medium">{template.question_text}</p>
                        {template.question_context && (
                          <p className="text-xs text-muted-foreground mt-1">
                            {template.question_context}
                          </p>
                        )}
                      </div>
                      {selectedTemplate?.id === template.id && (
                        <Check className="h-5 w-5 text-primary shrink-0" />
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </ScrollArea>
          </TabsContent>

          <TabsContent value="custom" className="mt-4 space-y-4">
            <div className="space-y-2">
              <Label htmlFor="question">Question *</Label>
              <Textarea
                id="question"
                placeholder="What would you like to ask the student?"
                value={customQuestion}
                onChange={(e) => {
                  setCustomQuestion(e.target.value);
                  setSelectedTemplate(null);
                }}
                rows={3}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="context">Context / Help Text</Label>
              <Textarea
                id="context"
                placeholder="Additional context to help the student understand what's needed..."
                value={customContext}
                onChange={(e) => setCustomContext(e.target.value)}
                rows={2}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Question Type</Label>
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                <Select value={questionType} onValueChange={(v) => setQuestionType(v as any)}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="information">Information</SelectItem>
                    <SelectItem value="document">Document</SelectItem>
                    <SelectItem value="lender_specific">Lender Specific</SelectItem>
                    <SelectItem value="conditional">Conditional</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Response Type</Label>
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                <Select value={responseType} onValueChange={(v) => setResponseType(v as any)}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="text">Text Only</SelectItem>
                    <SelectItem value="document">Document Upload</SelectItem>
                    <SelectItem value="both">Both</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          </TabsContent>
        </Tabs>

        <div className="border-t pt-4 mt-4 space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Priority</Label>
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              <Select value={priority} onValueChange={(v) => setPriority(v as any)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="low">Low</SelectItem>
                  <SelectItem value="normal">Normal</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                  <SelectItem value="urgent">Urgent</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Due Date (Optional)</Label>
              <DatePickerWithYearSelect
                date={dueDate ? new Date(dueDate) : undefined}
                setDate={(date) => setDueDate(date ? date.toISOString().split('T')[0] : "")}
                placeholder="Select due date"
                fromYear={new Date().getFullYear()}
                toYear={new Date().getFullYear() + 1}
                className="h-12"
              />
            </div>
          </div>
          <div className="flex items-center justify-between p-3 rounded-lg border bg-muted/50">
            <div>
              <Label htmlFor="blocking" className="font-medium">
                Blocking Question
              </Label>
              <p className="text-xs text-muted-foreground">
                If enabled, this will block the student's application progress
              </p>
            </div>
            <Switch
              id="blocking"
              checked={isBlocking}
              onCheckedChange={setIsBlocking}
            />
          </div>
        </div>

        <DialogFooter className="mt-4">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={isSubmitting || (!selectedTemplate && !customQuestion.trim())}
          >
            {isSubmitting ? 'Sending...' : 'Send to Student'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Copy } from 'lucide-react';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';
import { Calendar } from '@/components/ui/calendar';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { UserPlus, Search, MoreVertical, Edit, Eye, Shield, Building2, Users, XCircle, CheckCircle, Download, ChevronDown, CalendarIcon } from 'lucide-react';
import { useUserManagement, AppUser } from '@/hooks/useUserManagement';
import { useProtectedAccounts } from '@/hooks/useProtectedAccounts';
import CreateUserModal from './CreateUserModal';
import EditUserModal from './EditUserModal';
import UserDetailsSheet from './UserDetailsSheet';
import { DeactivateUserDialog } from './DeactivateUserDialog';
import { ReactivateUserDialog } from './ReactivateUserDialog';
import { formatDistanceToNow, format } from 'date-fns';
import Papa from 'papaparse';
import { useToast } from '@/hooks/use-toast';
import { cn } from '@/lib/utils';
import { formatDate } from '@/utils/formatters';

interface UserManagementTabProps {
  currentUserRole: 'admin' | 'super_admin';
  currentUserId: string;
}

const UserManagementTab = ({ currentUserRole, currentUserId }: UserManagementTabProps) => {
  const { users, partners, loading, fetchUsers, fetchPartners, deactivateUser, reactivateUser } = useUserManagement();
  const { isProtectedEmail } = useProtectedAccounts();
  const { toast } = useToast();
  const [searchTerm, setSearchTerm] = useState('');
  const [searchMode, setSearchMode] = useState<'email' | 'user_id' | 'partner_name'>('email');
  const [roleFilter, setRoleFilter] = useState<string>('all');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [dateFrom, setDateFrom] = useState<Date | undefined>();
  const [dateTo, setDateTo] = useState<Date | undefined>();
  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showDetailsSheet, setShowDetailsSheet] = useState(false);
  const [selectedUser, setSelectedUser] = useState<AppUser | null>(null);
  const [deactivateDialog, setDeactivateDialog] = useState<{ open: boolean; user: AppUser | null }>({ open: false, user: null });
  const [reactivateDialog, setReactivateDialog] = useState<{ open: boolean; user: AppUser | null }>({ open: false, user: null });
  const [isExporting, setIsExporting] = useState(false);

  useEffect(() => {
    fetchUsers();
    fetchPartners();
  }, [fetchUsers, fetchPartners]);

  const getPartnerName = (partnerId: string | null) => {
    if (!partnerId) return 'All Partners';
    const partner = partners.find((p) => p.id === partnerId);
    return partner ? partner.name : 'Unknown';
  };

  const filteredUsers = useMemo(() => {
    return users.filter((user) => {
      // Search filter based on mode
      let matchesSearch = true;
      if (searchTerm) {
        const searchLower = searchTerm.toLowerCase();
        switch (searchMode) {
          case 'email':
            matchesSearch = user.email.toLowerCase().includes(searchLower);
            break;
          case 'user_id':
            matchesSearch = user.id.toLowerCase().includes(searchLower);
            break;
          case 'partner_name': {
            const partnerName = getPartnerName(user.partner_id).toLowerCase();
            matchesSearch = partnerName.includes(searchLower);
            break;
          }
        }
      }

      // Role and status filters
      const matchesRole = roleFilter === 'all' || user.role === roleFilter;
      const matchesStatus = statusFilter === 'all' || (statusFilter === 'active' ? user.is_active : !user.is_active);

      // Date range filter
      let matchesDateRange = true;
      if (dateFrom || dateTo) {
        const userDate = new Date(user.created_at);
        if (dateFrom) {
          matchesDateRange = matchesDateRange && userDate >= dateFrom;
        }
        if (dateTo) {
          const endOfDay = new Date(dateTo);
          endOfDay.setHours(23, 59, 59, 999);
          matchesDateRange = matchesDateRange && userDate <= endOfDay;
        }
      }

      return matchesSearch && matchesRole && matchesStatus && matchesDateRange;
    });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [users, searchTerm, searchMode, roleFilter, statusFilter, dateFrom, dateTo]);
 

  const getRoleBadge = (role: string) => {
    switch (role) {
      case 'super_admin':
        return <Badge variant="destructive" className="gap-1"><Shield className="h-3 w-3" />Super Admin</Badge>;
      case 'admin':
        return <Badge variant="default" className="gap-1"><Shield className="h-3 w-3" />Admin</Badge>;
      case 'partner':
        return <Badge variant="secondary" className="gap-1"><Building2 className="h-3 w-3" />Partner</Badge>;
      default:
        return <Badge variant="outline">{role}</Badge>;
    }
  };

  const handleEdit = (user: AppUser) => {
    setSelectedUser(user);
    setShowEditModal(true);
  };

  const handleViewDetails = (user: AppUser) => {
    setSelectedUser(user);
    setShowDetailsSheet(true);
  };

  const handleDeactivateClick = (user: AppUser) => {
    setDeactivateDialog({ open: true, user });
  };

  const handleDeactivateConfirm = async (reason: string) => {
    if (deactivateDialog.user) {
      await deactivateUser(deactivateDialog.user.id, reason);
      setDeactivateDialog({ open: false, user: null });
    }
  };

  const handleReactivateClick = (user: AppUser) => {
    setReactivateDialog({ open: true, user });
  };

  const handleReactivateConfirm = async (reason: string) => {
    if (reactivateDialog.user) {
      await reactivateUser(reactivateDialog.user.id, reason);
      setReactivateDialog({ open: false, user: null });
    }
  };

  const canDeactivate = (user: AppUser) => {
    return (
      currentUserRole === 'super_admin' &&
      user.id !== currentUserId &&
      !isProtectedEmail(user.email) &&
      user.is_active
    );
  };

  const canReactivate = (user: AppUser) => {
    return currentUserRole === 'super_admin' && !user.is_active;
  };

  const exportToCSV = async () => {
    try {
      setIsExporting(true);

      // Prepare data for export
      const exportData = filteredUsers.map((user) => ({
        'Email': user.email,
        'Role': user.role,
        'Partner': getPartnerName(user.partner_id),
        'Status': user.is_active ? 'Active' : 'Inactive',
        'Created Date': formatDate(user.created_at, 'long'),
        'User ID': user.id,
        'Deactivation Reason': user.deactivation_reason || '',
        'Deactivated At': user.deactivated_at ? formatDate(user.deactivated_at, 'long') : ''
      }));

      // Generate CSV
      const csv = Papa.unparse(exportData);

      // Create download link
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      const url = URL.createObjectURL(blob);

      link.setAttribute('href', url);
      link.setAttribute('download', `users_export_${format(new Date(), 'yyyy-MM-dd_HH-mm')}.csv`);
      link.style.visibility = 'hidden';

      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      toast({
        title: 'Export Successful',
        description: `Exported ${filteredUsers.length} users to CSV`,
      });
    } catch (error) {
      console.error('Export error:', error);
      toast({
        title: 'Export Failed',
        description: 'Failed to export users. Please try again.',
        variant: 'destructive',
      });
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <>
      <div className="space-y-6">
        {/* Header */}
        <Card>
          <CardHeader className="pb-3">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Users className="h-5 w-5" />
                <CardTitle>User Management</CardTitle>
              </div>
              <div className="flex gap-2">
                <Button
                  onClick={exportToCSV}
                  size="sm"
                  variant="outline"
                  disabled={isExporting || filteredUsers.length === 0}
                >
                  <Download className="h-4 w-4 mr-2" />
                  {isExporting ? 'Exporting...' : 'Export CSV'}
                </Button>
                <Button onClick={() => setShowCreateModal(true)} size="sm">
                  <UserPlus className="h-4 w-4 mr-2" />
                  Create User
                </Button>
              </div>
            </div>
          </CardHeader>
          <CardContent>
            {/* Basic Search and Filters */}
            <div className="flex flex-col sm:flex-row gap-3">
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              <div className="flex-1 flex gap-2">
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                <Select value={searchMode} onValueChange={(value: any) => setSearchMode(value)}>
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                  <SelectTrigger className="w-[140px]">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="email">By Email</SelectItem>
                    <SelectItem value="user_id">By User ID</SelectItem>
                    <SelectItem value="partner_name">By Partner</SelectItem>
                  </SelectContent>
                </Select>
                <div className="relative flex-1">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    placeholder={
                      searchMode === 'email' ? 'Search by email...' :
                        searchMode === 'user_id' ? 'Search by user ID...' :
                          'Search by partner name...'
                    }
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pl-9"
                  />
                </div>
              </div>
              <Select value={roleFilter} onValueChange={setRoleFilter}>
                <SelectTrigger className="w-full sm:w-[150px]">
                  <SelectValue placeholder="All Roles" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Roles</SelectItem>
                  <SelectItem value="partner">Partner</SelectItem>
                  <SelectItem value="admin">Admin</SelectItem>
                  <SelectItem value="super_admin">Super Admin</SelectItem>
                </SelectContent>
              </Select>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-full sm:w-[150px]">
                  <SelectValue placeholder="All Status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="inactive">Inactive</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Advanced Filters - Collapsible */}
            <Collapsible open={showAdvancedFilters} onOpenChange={setShowAdvancedFilters} className="mt-4">
              <CollapsibleTrigger asChild>
                <Button variant="ghost" size="sm" className="w-full justify-between">
                  <span className="text-sm font-medium">Advanced Filters</span>
                  <ChevronDown className={cn("h-4 w-4 transition-transform", showAdvancedFilters && "rotate-180")} />
                </Button>
              </CollapsibleTrigger>
              <CollapsibleContent className="pt-4 space-y-3">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Created From</label>
                    <Popover>
                      <PopoverTrigger asChild>
                        <Button
                          variant="outline"
                          className={cn(
                            "w-full justify-start text-left font-normal",
                            !dateFrom && "text-muted-foreground"
                          )}
                        >
                          <CalendarIcon className="mr-2 h-4 w-4" />
                          {dateFrom ? format(dateFrom, 'PPP') : 'Pick a date'}
                        </Button>
                      </PopoverTrigger>
                      <PopoverContent className="w-auto p-0" align="start">
                        <Calendar
                          mode="single"
                          selected={dateFrom}
                          onSelect={setDateFrom}
                          initialFocus
                        />
                      </PopoverContent>
                    </Popover>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Created To</label>
                    <Popover>
                      <PopoverTrigger asChild>
                        <Button
                          variant="outline"
                          className={cn(
                            "w-full justify-start text-left font-normal",
                            !dateTo && "text-muted-foreground"
                          )}
                        >
                          <CalendarIcon className="mr-2 h-4 w-4" />
                          {dateTo ? format(dateTo, 'PPP') : 'Pick a date'}
                        </Button>
                      </PopoverTrigger>
                      <PopoverContent className="w-auto p-0" align="start">
                        <Calendar
                          mode="single"
                          selected={dateTo}
                          onSelect={setDateTo}
                          initialFocus
                        />
                      </PopoverContent>
                    </Popover>
                  </div>
                </div>
                {(dateFrom || dateTo) && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => {
                      setDateFrom(undefined);
                      setDateTo(undefined);
                    }}
                    className="w-full"
                  >
                    Clear Date Filters
                  </Button>
                )}
              </CollapsibleContent>
            </Collapsible>
          </CardContent>
        </Card>

        {/* Users Table */}
        <Card>
          <CardContent className="p-0">
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="w-[100px]">User ID</TableHead>
                    <TableHead>Email</TableHead>
                    <TableHead>Role</TableHead>
                    <TableHead>Assignment</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Created</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {loading ? (
                    <TableRow>
                      <TableCell colSpan={7} className="text-center py-8 text-muted-foreground">
                        Loading users...
                      </TableCell>
                    </TableRow>
                  ) : filteredUsers.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={7} className="text-center py-8 text-muted-foreground">
                        No users found
                      </TableCell>
                    </TableRow>
                  ) : (
                    filteredUsers.map((user) => {
                      const isProtected = isProtectedEmail(user.email);
                      return (
                        <TableRow key={user.id}>
                          <TableCell className="font-mono text-xs">
                            <div className="flex items-center gap-1">
                              <span className="truncate max-w-[80px]" title={user.id}>
                                {user.id.slice(0, 8)}...
                              </span>
                              <Button
                                variant="ghost"
                                size="sm"
                                className="h-5 w-5 p-0"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  navigator.clipboard.writeText(user.id);
                                  toast({ title: 'Copied', description: 'User ID copied to clipboard' });
                                }}
                              >
                                <Download className="h-3 w-3" />
                              </Button>
                            </div>
                          </TableCell>
                          <TableCell className="font-medium">
                            {user.email}
                            {isProtected && <Shield className="inline h-3 w-3 ml-1 text-destructive" />}
                          </TableCell>
                          <TableCell>{getRoleBadge(user.role)}</TableCell>
                          <TableCell className="text-sm text-muted-foreground">
                            {getPartnerName(user.partner_id)}
                          </TableCell>
                          <TableCell>
                            <Badge variant={user.is_active ? 'default' : 'outline'}>
                              {user.is_active ? '🟢 Active' : '🔴 Inactive'}
                            </Badge>
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground">
                            {formatDistanceToNow(new Date(user.created_at), { addSuffix: true })}
                          </TableCell>
                          <TableCell className="text-right">
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild>
                                <Button variant="ghost" size="sm">
                                  <MoreVertical className="h-4 w-4" />
                                </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end">
                                <DropdownMenuItem onClick={() => handleViewDetails(user)}>
                                  <Eye className="h-4 w-4 mr-2" />
                                  View Details
                                </DropdownMenuItem>
                                {!isProtected && (
                                  <DropdownMenuItem onClick={() => handleEdit(user)}>
                                    <Edit className="h-4 w-4 mr-2" />
                                    Edit User
                                  </DropdownMenuItem>
                                )}
                                {canReactivate(user) && (
                                  <>
                                    <DropdownMenuSeparator />
                                    <DropdownMenuItem
                                      onClick={() => handleReactivateClick(user)}
                                      className="text-green-600"
                                    >
                                      <CheckCircle className="h-4 w-4 mr-2" />
                                      Reactivate User
                                    </DropdownMenuItem>
                                  </>
                                )}
                                {canDeactivate(user) && (
                                  <>
                                    <DropdownMenuSeparator />
                                    <DropdownMenuItem
                                      onClick={() => handleDeactivateClick(user)}
                                      className="text-destructive"
                                    >
                                      <XCircle className="h-4 w-4 mr-2" />
                                      Deactivate User
                                    </DropdownMenuItem>
                                  </>
                                )}
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </TableCell>
                        </TableRow>
                      );
                    })
                  )}
                </TableBody>
              </Table>
            </div>
          </CardContent>
        </Card>

        <div className="text-sm text-muted-foreground">
          Showing {filteredUsers.length} of {users.length} users
        </div>
      </div>

      {/* Modals */}
      <CreateUserModal
        open={showCreateModal}
        onOpenChange={setShowCreateModal}
        currentUserRole={currentUserRole}
      />
      <EditUserModal
        open={showEditModal}
        onOpenChange={setShowEditModal}
        user={selectedUser}
        currentUserRole={currentUserRole}
      />
      <UserDetailsSheet
        open={showDetailsSheet}
        onOpenChange={setShowDetailsSheet}
        user={selectedUser}
      />

      {/* Deactivate/Reactivate Dialogs */}
      <DeactivateUserDialog
        open={deactivateDialog.open}
        onOpenChange={(open) => setDeactivateDialog({ open, user: null })}
        onConfirm={handleDeactivateConfirm}
        userEmail={deactivateDialog.user?.email || ''}
        loading={loading}
      />
      <ReactivateUserDialog
        open={reactivateDialog.open}
        onOpenChange={(open) => setReactivateDialog({ open, user: null })}
        onConfirm={handleReactivateConfirm}
        userEmail={reactivateDialog.user?.email || ''}
        loading={loading}
      />
    </>
  );
};

export default UserManagementTab;

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Plus, Eye, MoreHorizontal, Users, TrendingUp, Edit, Info } from 'lucide-react';
import { TableSkeleton } from '@/components/common/LoadingStates';
import { usePartnerStats } from '@/hooks/usePartnerStats';
import { formatRelativeTime } from '@/utils/formatters';
import CreatePartnerModal from '@/components/admin/CreatePartnerModal';
import { EditPartnerModal } from '@/components/admin/EditPartnerModal';
import { PartnerDetailsSheet } from '@/components/admin/PartnerDetailsSheet';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';

interface Partner {
  id: string;
  name: string;
  partner_code: string;
  email: string;
  phone?: string | null;
  address?: string | null;
  is_active: boolean;
  created_at: string;
  totalLeads: number;
  activeLenders: number;
  recentActivity: string | null;
}

interface AdminPartnersTabProps {
  onViewLeads?: (partnerId: string) => void;
}

export const AdminPartnersTab = ({ onViewLeads }: AdminPartnersTabProps) => {
  const { stats, loading, refetch } = usePartnerStats();
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showDetailsSheet, setShowDetailsSheet] = useState(false);
  const [selectedPartner, setSelectedPartner] = useState<Partner | null>(null);

  const totalPartners = stats.length;
  const totalLeadsViaPartners = stats.reduce((sum, p) => sum + p.totalLeads, 0);

  const handleViewDetails = (partner: Partner) => {
    setSelectedPartner(partner);
    setShowDetailsSheet(true);
  };

  const handleEdit = (partner: Partner) => {
    setSelectedPartner(partner);
    setShowEditModal(true);
  };

  const handleEditFromSheet = () => {
    setShowDetailsSheet(false);
    setShowEditModal(true);
  };

  const handleViewLeadsFromSheet = () => {
    if (selectedPartner && onViewLeads) {
      setShowDetailsSheet(false);
      onViewLeads(selectedPartner.id);
    }
  };

  if (loading) return <TableSkeleton rows={8} columns={5} />;

  return (
    <div className="space-y-4">
      {/* Quick Stats */}
      <div className="grid grid-cols-2 gap-4">
        <Card>
          <CardContent className="p-4 flex items-center gap-3">
            <div className="p-2 bg-primary/10 rounded-lg">
              <Users className="h-5 w-5 text-primary" />
            </div>
            <div>
              <p className="text-2xl font-semibold">{totalPartners}</p>
              <p className="text-sm text-muted-foreground">Total Partners</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 flex items-center gap-3">
            <div className="p-2 bg-green-500/10 rounded-lg">
              <TrendingUp className="h-5 w-5 text-green-600" />
            </div>
            <div>
              <p className="text-2xl font-semibold">{totalLeadsViaPartners}</p>
              <p className="text-sm text-muted-foreground">Leads via Partners</p>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Partners Table */}
      <Card>
        <CardHeader className="flex flex-row items-center justify-between py-4">
          <CardTitle className="text-lg">Partners</CardTitle>
          <Button size="sm" onClick={() => setShowCreateModal(true)}>
            <Plus className="mr-2 h-4 w-4" />
            Add Partner
          </Button>
        </CardHeader>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Partner Name</TableHead>
                <TableHead>Partner Code</TableHead>
                <TableHead className="text-center">Total Leads</TableHead>
                <TableHead className="text-center">Status</TableHead>
                <TableHead>Last Activity</TableHead>
                <TableHead className="w-[100px]">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {stats.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} className="text-center py-8 text-muted-foreground">
                    No partners found. Create your first partner to get started.
                  </TableCell>
                </TableRow>
              ) : (
                stats.map((partner) => (
                  <TableRow key={partner.id} className="cursor-pointer hover:bg-muted/50" onClick={() => handleViewDetails(partner as Partner)}>
                    <TableCell className="font-medium">{partner.name}</TableCell>
                    <TableCell>
                      <Badge variant="outline">{partner.partner_code}</Badge>
                    </TableCell>
                    <TableCell className="text-center">{partner.totalLeads}</TableCell>
                    <TableCell className="text-center">
                      // eslint-disable-next-line @typescript-eslint/no-explicit-any
                      <Badge variant={(partner as any).is_active !== false ? 'default' : 'secondary'}>
                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                        {(partner as any).is_active !== false ? 'Active' : 'Inactive'}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-muted-foreground text-sm">
                      {formatRelativeTime(partner.recentActivity)}
                    </TableCell>
                    <TableCell>
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
                          <Button variant="ghost" size="icon" className="h-8 w-8">
                            <MoreHorizontal className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={(e) => { e.stopPropagation(); handleViewDetails(partner as Partner); }}>
                            <Info className="mr-2 h-4 w-4" />
                            View Details
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={(e) => { e.stopPropagation(); handleEdit(partner as Partner); }}>
                            <Edit className="mr-2 h-4 w-4" />
                            Edit Partner
                          </DropdownMenuItem>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem onClick={(e) => { e.stopPropagation(); onViewLeads?.(partner.id); }}>
                            <Eye className="mr-2 h-4 w-4" />
                            View Leads
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* Create Partner Modal */}
      <CreatePartnerModal
        open={showCreateModal}
        onOpenChange={setShowCreateModal}
        onPartnerCreated={() => {
          refetch();
          setShowCreateModal(false);
        }}
      />

      {/* Edit Partner Modal */}
      <EditPartnerModal
        open={showEditModal}
        onOpenChange={setShowEditModal}
        partner={selectedPartner}
        onPartnerUpdated={() => {
          refetch();
          setSelectedPartner(null);
        }}
      />

      {/* Partner Details Sheet */}
      <PartnerDetailsSheet
        open={showDetailsSheet}
        onOpenChange={setShowDetailsSheet}
        partner={selectedPartner}
        stats={selectedPartner ? {
          totalLeads: selectedPartner.totalLeads,
          activeLenders: selectedPartner.activeLenders,
          recentActivity: selectedPartner.recentActivity,
        } : undefined}
        onEdit={handleEditFromSheet}
        onViewLeads={handleViewLeadsFromSheet}
      />
    </div>
  );
};

/**
 * Student Dashboard - Compact Redesign
 * 
 * 3-section layout:
 * 1. CompactStatusHeader - Journey card with status
 * 2. ApplicationDetailsCard - Basic info with edit button
 * 3. CollapsibleDocumentSection - Documents with filter tabs
 */
import { useEffect, useState, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { useAuth } from '@/hooks/useAuth';

const LOADING_TIMEOUT_MS = 15000; // 15 second max loading time (auth can be slow)
import { supabase } from '@/integrations/supabase/client';
import { filterLeadForStudent } from '@/utils/rolePermissions';
import { STUDENT_EDIT_LOCKED_STATUSES } from '@/constants/studentPermissions';
import ChangeLenderModal from '@/components/student/ChangeLenderModal';
import StudentUploadSheet from '@/components/student/StudentUploadSheet';
import { toast } from 'sonner';
import {
  CompactStatusHeader,
  ApplicationDetailsCard,
  CollapsibleDocumentSection,
  type DocumentItem,
} from '@/components/student/dashboard';
import { generateProcessGuidePDF } from '@/utils/generateProcessGuidePDF';
import {
  LogOut,
  GraduationCap,
  Sparkles,
  ChevronRight,
  Globe,
  Shield
} from 'lucide-react';
import { motion } from 'framer-motion';

interface StudentLead {
  id: string;
  case_id: string;
  status: string;
  loan_amount: number;
  study_destination: string;
  intake_month: number | null;
  intake_year: number | null;
  documents_status: string;
  created_at: string;
  target_lender_id: string | null;
  lender_id: string | null;
  partner?: { name: string } | null;
  target_lender?: { id: string; name: string; code?: string } | null;
}

interface StudentProfile {
  id: string;
  name: string;
  email: string;
  phone: string;
}

interface DocumentType {
  id: string;
  name: string;
  category: string;
  description: string | null;
  required: boolean;
}

interface UploadedDoc {
  id: string;
  document_type_id: string;
  verification_status: string;
  original_filename: string;
  verification_notes: string | null;
}

const StudentDashboard = () => {
  const navigate = useNavigate();
  const { user, signOut, loading: authLoading } = useAuth();
  const [loading, setLoading] = useState(true);
  const [lead, setLead] = useState<StudentLead | null>(null);
  const [profile, setProfile] = useState<StudentProfile | null>(null);
  const [hasLead, setHasLead] = useState(false);
  const [showChangeLender, setShowChangeLender] = useState(false);
  const [showUploadSheet, setShowUploadSheet] = useState(false);
  const [loadingTimedOut, setLoadingTimedOut] = useState(false);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  // Document state
  const [documentTypes, setDocumentTypes] = useState<DocumentType[]>([]);
  const [uploadedDocs, setUploadedDocs] = useState<UploadedDoc[]>([]);
  const [uploadingId, setUploadingId] = useState<string | null>(null);

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const isEditLocked = lead ? STUDENT_EDIT_LOCKED_STATUSES.includes(lead.status as any) : true;

  const fetchStudentData = useCallback(async () => {
    if (!user?.email) return;

    try {
      let studentData = null;

      // PHONE-FIRST LOOKUP: If synthetic email, extract phone and lookup by phone first
      // This is more reliable since phone is the student's primary identity
      const syntheticMatch = user.email.match(/^(\d{10})@student\.loan\.app$/i);

      if (syntheticMatch) {
        // Synthetic OTP email - lookup by phone FIRST
        const phoneDigits = syntheticMatch[1];
        console.log('[StudentDashboard] Synthetic email detected, looking up by phone:', phoneDigits);

        const { data: byPhone, error: phoneError } = await supabase
          .from('students')
          .select('id, name, email, phone')
          .eq('phone', phoneDigits)
          .maybeSingle();

        if (!phoneError && byPhone) {
          studentData = byPhone;
          console.log('[StudentDashboard] Found student by phone:', studentData.id);
        }
      }

      // If not found by phone (or not synthetic), try email lookup
      if (!studentData) {
        const { data: byEmail, error: emailError } = await supabase
          .from('students')
          .select('id, name, email, phone')
          .eq('email', user.email)
          .maybeSingle();

        if (!emailError && byEmail) {
          studentData = byEmail;
          console.log('[StudentDashboard] Found student by email:', studentData.id);
        } else {
          // Final fallback: Extract any 10 digits from email
          const emailMatch = user.email.match(/(\d{10})/);
          if (emailMatch) {
            const phoneDigits = emailMatch[1];
            const { data: byPhone, error: phoneError } = await supabase
              .from('students')
              .select('id, name, email, phone')
              .eq('phone', phoneDigits)
              .maybeSingle();

            if (!phoneError && byPhone) {
              studentData = byPhone;
              console.log('[StudentDashboard] Found student by extracted phone:', studentData.id);
            }
          }
        }
      }

      if (studentData) {
        setProfile(studentData);

        const { data: leadData, error: leadError } = await supabase
          .from('leads_new')
          .select(`
            id, case_id, status, loan_amount, study_destination,
            intake_month, intake_year, documents_status, created_at,
            target_lender_id, lender_id,
            partner:partners(name),
            target_lender:lenders!leads_new_target_lender_id_fkey(id, name, code)
          `)
          .eq('student_id', studentData.id)
          .order('created_at', { ascending: false })
          .limit(1)
          .maybeSingle();

        if (!leadError && leadData) {
          const filteredLead = filterLeadForStudent(leadData);
          setLead({
            ...filteredLead,
            target_lender_id: leadData.target_lender_id,
            lender_id: leadData.lender_id,
            partner: leadData.partner,
            target_lender: leadData.target_lender,
          } as StudentLead);
          setHasLead(true);
          console.log('[StudentDashboard] Found lead:', leadData.case_id);

          // Fetch documents for this lead
          await fetchDocuments(leadData.id);
        } else {
          console.log('[StudentDashboard] No lead found for student');
        }
      } else {
        console.log('[StudentDashboard] No student profile found');
      }
    } catch (err) {
      console.error('Error fetching student data:', err);
    } finally {
      setLoading(false);
    }
  }, [user?.email]);

  const fetchDocuments = async (leadId: string) => {
    const [typesRes, docsRes] = await Promise.all([
      supabase
        .from('document_types')
        .select('id, name, category, description, required')
        .order('display_order', { ascending: true }),
      supabase
        .from('lead_documents')
        .select('id, document_type_id, verification_status, original_filename, verification_notes')
        .eq('lead_id', leadId)
    ]);

    setDocumentTypes(typesRes.data || []);
    setUploadedDocs(docsRes.data || []);
  };

  // Wait for auth to finish before fetching student data
  // Key fix: Don't give up too early on slow auth, retry when user becomes available
  useEffect(() => {
    let isMounted = true;

    // Clear any existing timeout
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    const attemptFetch = async () => {
      // If we have a user email, try to fetch student data
      if (user?.email) {
        console.log('[StudentDashboard] User available, fetching student data:', user.email);
        await fetchStudentData();
        return true;
      }
      return false;
    };

    // If auth is still loading, wait for it - but set a max timeout
    if (authLoading) {
      console.log('[StudentDashboard] Auth still loading, waiting...');

      // Set a safety timeout - if auth takes too long, we'll check again
      timeoutRef.current = setTimeout(() => {
        if (isMounted && !user) {
          console.log('[StudentDashboard] Auth timeout, checking one more time...');
          setLoadingTimedOut(true);
          setLoading(false);
        }
      }, LOADING_TIMEOUT_MS);

      return () => {
        isMounted = false;
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
      };
    }

    // Auth finished - now we can make decisions
    if (!user) {
      // No user after auth complete - stop loading
      console.log('[StudentDashboard] No user after auth complete, stopping load');
      setLoading(false);
      return;
    }

    // We have a user - fetch their data
    attemptFetch();

    return () => {
      isMounted = false;
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authLoading, user?.email, fetchStudentData]);


  const handleLogout = async () => {
    if (window.confirm('Are you sure you want to logout?')) {
      await signOut();
      navigate('/');
    }
  };

  const handleUploadDocuments = () => {
    setShowUploadSheet(true);
  };

  const handleStartApplication = () => {
    navigate('/student/apply');
  };

  const handleEditApplication = () => {
    navigate('/student/apply');
  };

  const handleDownloadProcessGuide = () => {
    if (!profile || !lead || !lead.target_lender) return;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    generateProcessGuidePDF({
      studentName: profile.name,
      loanAmount: lead.loan_amount,
      studyDestination: lead.study_destination,
      targetLenderName: lead.target_lender.name || (lead.target_lender as any).name || 'Lender',
    });
    // Add toast to let user know
    toast.success('Your process guide is being downloaded');
  };

  // Document helpers
  const getDocumentStatus = (typeId: string): 'required' | 'pending' | 'verified' | 'rejected' => {
    const doc = uploadedDocs.find(d => d.document_type_id === typeId);
    if (!doc) return 'required';
    if (doc.verification_status === 'verified') return 'verified';
    if (doc.verification_status === 'rejected') return 'rejected';
    return 'pending';
  };

  const handleFileUpload = async (typeId: string, file: File) => {
    if (!lead || !file) return;

    if (file.size > 10 * 1024 * 1024) {
      toast.error('File size must be less than 10MB');
      return;
    }

    setUploadingId(typeId);

    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${lead.id}/${typeId}/${Date.now()}.${fileExt}`;

      const { error: uploadError } = await supabase.storage
        .from('lead-documents')
        .upload(fileName, file);

      if (uploadError) throw uploadError;

      const { data: newDoc, error: dbError } = await supabase
        .from('lead_documents')
        .insert({
          lead_id: lead.id,
          document_type_id: typeId,
          file_path: fileName,
          stored_filename: fileName,
          original_filename: file.name,
          file_size: file.size,
          mime_type: file.type,
          verification_status: 'pending',
          uploaded_by: 'student'
        })
        .select()
        .single();

      if (dbError) throw dbError;

      setUploadedDocs(prev => [...prev, newDoc]);
      toast.success('Document uploaded successfully');
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) {
      toast.error(err.message || 'Upload failed');
    } finally {
      setUploadingId(null);
    }
  };

  // Calculate stats
  const requiredDocs = documentTypes.filter(d => d.required);
  const pendingCount = requiredDocs.filter(d => getDocumentStatus(d.id) === 'required').length;
  const uploadedCount = requiredDocs.filter(d => {
    const status = getDocumentStatus(d.id);
    return status === 'pending';
  }).length;
  const rejectedCount = requiredDocs.filter(d => getDocumentStatus(d.id) === 'rejected').length;
  const verifiedCount = requiredDocs.filter(d => getDocumentStatus(d.id) === 'verified').length;
  const totalDocs = requiredDocs.length;

  // Build document items for table
  const documentItems: DocumentItem[] = requiredDocs.map(doc => {
    const uploaded = uploadedDocs.find(u => u.document_type_id === doc.id);
    return {
      id: doc.id,
      name: doc.name,
      category: doc.category,
      description: doc.description,
      status: getDocumentStatus(doc.id),
      rejectionReason: uploaded?.verification_notes || undefined,
      uploadedFilename: uploaded?.original_filename,
    };
  });

  const rawName = profile?.name?.split(' ')[0] || 'there';
  const studentName = rawName.charAt(0).toUpperCase() + rawName.slice(1).toLowerCase();

  const getInitials = (name: string) => {
    return name?.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2) || 'ST';
  };

  // Handle session recovery
  const handleRefreshSession = async () => {
    setLoading(true);
    setLoadingTimedOut(false);
    try {
      const { error } = await supabase.auth.refreshSession();
      if (error) {
        console.error('[StudentDashboard] Session refresh failed:', error);
        toast.error('Session expired. Please login again.');
        navigate('/login/student');
        return;
      }
      // Retry fetching data
      await fetchStudentData();
    } catch (err) {
      console.error('[StudentDashboard] Refresh error:', err);
      navigate('/login/student');
    }
  };

  const handleLogoutAndRetry = async () => {
    await signOut();
    navigate('/login/student');
  };

  // Show loading only if auth is still loading or we're fetching data
  if (loading && !loadingTimedOut) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-muted/30 via-background to-background">
        {/* Skeleton Header */}
        <header className="sticky top-0 z-50 backdrop-blur-xl bg-background/80 border-b border-border">
          <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-xl bg-muted animate-pulse" />
                <div className="w-24 h-4 bg-muted rounded animate-pulse" />
              </div>
              <div className="w-20 h-8 bg-muted rounded animate-pulse" />
            </div>
          </div>
        </header>

        {/* Skeleton Content */}
        <main className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8 lg:py-12">
          <div className="space-y-4">
            {/* Skeleton Status Card */}
            <div className="h-24 bg-muted rounded-xl animate-pulse" />
            {/* Skeleton Application Details */}
            <div className="h-32 bg-muted rounded-xl animate-pulse" />
            {/* Skeleton Documents Section */}
            <div className="h-48 bg-muted rounded-xl animate-pulse" />
          </div>
          <p className="text-center text-sm text-muted-foreground mt-8 animate-pulse">
            Loading your dashboard...
          </p>
        </main>
      </div>
    );
  }

  // If loading timed out or no user after auth - show recovery UI
  if ((loadingTimedOut && !profile) || (!authLoading && !user)) {
    return (
      <div className="min-h-screen bg-background flex flex-col items-center justify-center gap-6 px-4">
        <div className="text-center">
          <GraduationCap className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
          <h2 className="text-lg font-semibold mb-2">Session Issue</h2>
          <p className="text-muted-foreground text-center max-w-sm">
            {!user
              ? "Your session may have expired. Please try refreshing or login again."
              : "Something went wrong loading your data."
            }
          </p>
        </div>
        <div className="flex gap-3">
          <Button variant="outline" onClick={handleRefreshSession}>
            Refresh Session
          </Button>
          <Button onClick={handleLogoutAndRetry}>
            Login Again
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-muted/30 via-background to-background">
      {/* Header */}
      <header className="sticky top-0 z-50 backdrop-blur-xl bg-background/80 border-b border-border">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 rounded-xl bg-primary flex items-center justify-center">
                <GraduationCap className="w-5 h-5 text-primary-foreground" />
              </div>
              <div className="flex flex-col">
                <span className="font-semibold text-lg text-foreground leading-tight">Eduloans</span>
                <span className="text-[10px] text-muted-foreground">by cashakro</span>
              </div>
            </div>

            <div className="flex items-center gap-4">
              {profile && hasLead && lead && (
                <div className="hidden md:flex items-center gap-3 px-4 py-2 rounded-full bg-muted/50 border border-border">
                  <div className="w-6 h-6 rounded-full bg-primary flex items-center justify-center">
                    <span className="text-[10px] font-bold text-primary-foreground">
                      {getInitials(profile.name)}
                    </span>
                  </div>
                  <span className="text-sm font-medium">{studentName}</span>
                </div>
              )}
              <Button
                variant="ghost"
                size="sm"
                onClick={handleLogout}
                className="text-muted-foreground hover:text-foreground"
              >
                <LogOut className="w-4 h-4 mr-2" />
                Logout
              </Button>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8 lg:py-12">
        {!hasLead ? (
          /* ================== NO APPLICATION STATE ================== */
          <motion.div
            className="max-w-xl mx-auto text-center pt-12"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
          >
            <div className="inline-flex items-center justify-center w-24 h-24 rounded-full bg-gradient-to-br from-primary/20 to-primary/5 mb-8">
              <Globe className="w-12 h-12 text-primary" />
            </div>

            <h1 className="text-4xl sm:text-5xl font-bold text-foreground mb-4">
              Your Dream Abroad<br />
              <span className="text-primary">Starts Here</span>
            </h1>

            <p className="text-lg text-muted-foreground mb-10">
              Get personalized loan offers in just 5 minutes
            </p>

            <Button
              onClick={handleStartApplication}
              size="lg"
              className="h-14 px-12 text-lg font-semibold shadow-lg shadow-primary/20"
            >
              <Sparkles className="w-5 h-5 mr-2" />
              Start Application
              <ChevronRight className="w-5 h-5 ml-1" />
            </Button>
          </motion.div>
        ) : (
          /* ================== HAS APPLICATION - COMPACT 3-SECTION DASHBOARD ================== */
          <motion.div
            className="space-y-4"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
          >
            {/* Section 1: Compact Status Header (Journey Card) */}
            <CompactStatusHeader
              caseId={lead.case_id}
              status={lead.status}
            />

            {/* Section 2: Application Details Card */}
            <ApplicationDetailsCard
              loanAmount={lead.loan_amount}
              studyDestination={lead.study_destination}
              intakeMonth={lead.intake_month}
              intakeYear={lead.intake_year}
              targetLender={lead.target_lender}
              createdAt={lead.created_at}
              isEditLocked={isEditLocked}
              onEditClick={handleEditApplication}
              onDownloadGuide={handleDownloadProcessGuide}
            />

            {/* Section 3: Collapsible Document Section */}
            <CollapsibleDocumentSection
              documents={documentItems}
              pendingCount={pendingCount}
              uploadedCount={uploadedCount}
              rejectedCount={rejectedCount}
              verifiedCount={verifiedCount}
              totalCount={totalDocs}
              onUploadClick={handleUploadDocuments}
              onFileUpload={handleFileUpload}
              uploadingId={uploadingId}
            />

            {/* Trust Footer */}
            <div className="flex items-center justify-center gap-2 pt-6 pb-4 text-xs text-muted-foreground/70">
              <Shield className="w-3.5 h-3.5" />
              <span>Your documents are securely shared only with verified lenders</span>
            </div>
          </motion.div>
        )}
      </main>

      {/* Change Lender Modal */}
      {lead && (
        <ChangeLenderModal
          open={showChangeLender}
          onOpenChange={setShowChangeLender}
          leadId={lead.id}
          currentLenderId={lead.target_lender_id}
          onLenderChanged={fetchStudentData}
        />
      )}

      {/* Upload Sheet */}
      {lead && (
        <StudentUploadSheet
          open={showUploadSheet}
          onOpenChange={setShowUploadSheet}
          leadId={lead.id}
          studentName={profile?.name}
          onUploadComplete={async () => {
            await fetchDocuments(lead.id);
          }}
          documentTypes={documentTypes}
          uploadedDocs={uploadedDocs}
        />
      )}
    </div>
  );
};

export default StudentDashboard;
